var a=`0199-paella-valenciana`;var i=`world-0199`;var n=`ES`;var r=`southern-europe`;var o=4;var s=45;var l={en:`Paella Valenciana`,ua:`Паелья по-валенсійськи`};var g={en:`A classic dish from Spain, featuring chicken thigh, rabbit meat, green beans, tomato. A practical home-kitchen version with measured step ingredients and clear cooking methods.`,ua:`Класична страва з Іспанія. Основні складники: куряче стегно, кролятина, стручкова квасоля, помідор. Домашній варіант із поетапними діями та точними кількостями продуктів.`};var h=[{en:`Brown the chicken and rabbit pieces thoroughly in olive oil in a wide paella pan.`,ua:`Добре підрум’яньте шматочки курятини та кролятини в оливковій олії на широкій сковороді для паельї.`,t:[`searing`],m:12,i:[[`chicken-thigh`,480,`g`],[`rabbit-meat`,350,`g`],[`extra-virgin-olive-oil`,100,`ml`]]},{en:`Add green beans and grated tomato; soften, then briefly bloom paprika without burning it.`,ua:`Додайте зелену квасолю й натерті помідори, припустіть; коротко прогрійте паприку, не даючи їй підгоріти.`,t:[`chopping`,`sauteing`],m:8,i:[[`green-beans`,220,`g`],[`tomato`,250,`g`],[`sweet-paprika`,6,`g`]]},{en:`Pour in the measured water with the saffron and butter beans; let the meat-and-vegetable broth simmer to develop flavor, then add rice. Cook without stirring for 17–20 minutes, allowing a thin socarrat to form at the base.`,ua:`Влийте зазначену воду, додайте шафран і квасолю, проваріть м’ясо-овочевий бульйон, тоді всипте рис. Готуйте 17–20 хвилин, не перемішуючи, щоб на дні утворився тонкий сокаррат.`,t:[`rice-washing`,`absorption-cooking`],m:20,i:[[`bomba-rice`,390,`g`],[`water`,1400,`ml`],[`butter-beans`,160,`g`],[`saffron-threads`,.2,`g`],[`table-salt`,null,`to_taste`]]},{en:`Turn off the heat, cover loosely and let the rice rest 5 minutes before serving.`,ua:`Вимкніть вогонь, нещільно накрийте та дайте рису відпочити 5 хвилин перед подаванням.`,t:[`rice-resting`,`fluffing-grains`],m:5,i:[[`rosemary`,1,`sprig`]]}];var u={slug:a,id:i,country:`ES`,region:r,servings:4,minutes:45,title:l,text:g,steps:h};export{n as country,u as default,i as id,s as minutes,r as region,o as servings,a as slug,h as steps,g as text,l as title};